return ['domain'=>'pnscripts-pricetrail','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de_DE','project-id-version'=>'PN Scripts Pricetrail 1.0.2','pot-creation-date'=>'2026-10-04T14:15:47+00:00','po-revision-date'=>'2026-10-04 17:00+0300','x-generator'=>'WP-CLI 2.12.0','messages'=>['PN Scripts Pricetrail – 30-Day Lowest Price for Sales'=>'PN Scripts Pricetrail – niedrigster 30-Tage-Preis für Rabattaktionen','https://pnscripts.com/marketplace/pn-omnibus'=>'https://pnscripts.com/marketplace/pn-omnibus','Records every product and variation price change and shows the lowest price in the 30 days before a discount (EU Price Indication Directive, Art. 6a). Shows nothing when the history is incomplete.'=>'Speichert jede Preisänderung von Produkten und Varianten und zeigt den niedrigsten Preis der 30 Tage vor einer Preisermäßigung (Preisangabenrichtlinie, Art. 6a). Zeigt nichts an, wenn die Preishistorie unvollständig ist.','PN Scripts'=>'PN Scripts','https://pnscripts.com'=>'https://pnscripts.com','Perishable goods'=>'Schnell verderbliche Waren','Products in this category perish or expire quickly. Only used when the perishable-goods exemption is enabled in Pricetrail settings.'=>'Produkte dieser Kategorie verderben schnell oder haben eine kurze Haltbarkeit. Wird nur verwendet, wenn die Ausnahme für schnell verderbliche Waren in den Pricetrail-Einstellungen aktiviert ist.','Products in this category perish or expire quickly.'=>'Produkte dieser Kategorie verderben schnell oder haben eine kurze Haltbarkeit.','Shown'=>'Angezeigt','Not on sale'=>'Nicht reduziert','Exempt'=>'Ausgenommen','Unknown, hidden'=>'Unbekannt, ausgeblendet','No price history has been recorded yet.'=>'Es wurde noch keine Preishistorie gespeichert.','Prices during part of the period are unknown (the plugin was inactive or prices were changed outside WooCommerce).'=>'Die Preise für einen Teil des Zeitraums sind unbekannt (das Plugin war inaktiv oder Preise wurden außerhalb von WooCommerce geändert).','The recorded history does not cover the whole period before the discount yet.'=>'Die gespeicherte Historie deckt den Zeitraum vor der Preisermäßigung noch nicht vollständig ab.','The product was launched less than the period before the discount and the current rules hide the notice for such products.'=>'Das Produkt ist kürzer als der Zeitraum vor der Preisermäßigung im Angebot, und die aktuellen Regeln blenden den Hinweis für solche Produkte aus.','The product was already on sale when recording started, so the start of the discount is unknown.'=>'Das Produkt war bereits reduziert, als die Aufzeichnung begann; der Beginn der Preisermäßigung ist daher unbekannt.','There is no price before the discount (the product was launched on sale or had no price).'=>'Es gibt keinen Preis vor der Preisermäßigung (das Produkt wurde bereits reduziert eingeführt oder hatte keinen Preis).','WooCommerce shows a discount that is not in the recorded prices (for example a price changed by another plugin on the fly).'=>'WooCommerce zeigt eine Preisermäßigung, die nicht in den gespeicherten Preisen enthalten ist (z. B. ein Preis, den ein anderes Plugin laufend ändert).','Marked as perishable and the perishable-goods exemption is enabled.'=>'Als schnell verderblich markiert, und die Ausnahme für schnell verderbliche Waren ist aktiviert.','Variable and grouped products are evaluated per variation or child product.'=>'Variable und gruppierte Produkte werden pro Variante bzw. Einzelprodukt bewertet.','The tax settings or rates changed during the period, so earlier prices cannot be converted with today\'s taxes.'=>'Die Steuereinstellungen oder Steuersätze wurden im Zeitraum geändert, daher können frühere Preise nicht mit den heutigen Steuern umgerechnet werden.','Product editor'=>'Produkteditor','Quick edit'=>'QuickEdit','Bulk edit'=>'Mehrfachbearbeitung','CSV import'=>'CSV-Import','REST API'=>'REST-API','WP-CLI'=>'WP-CLI','Background task'=>'Hintergrundaufgabe','Scheduled sale'=>'Geplantes Angebot','AJAX'=>'AJAX','Code'=>'Code','First record'=>'Erster Eintrag','After inactivity'=>'Nach Inaktivität','Repair'=>'Reparatur','Imported (Omnibus by iWorks)'=>'Importiert (Omnibus von iWorks)','Imported (WC Price History)'=>'Importiert (WC Price History)','Imported (Omnibus by iLabs)'=>'Importiert (Omnibus by iLabs)','Price history and lowest prior price'=>'Preishistorie und niedrigster vorheriger Preis','Recorded automatically on every price change. This plugin helps display prices; you remain responsible for compliance.'=>'Wird bei jeder Preisänderung automatisch gespeichert. Dieses Plugin hilft bei der Preisanzeige; die Verantwortung für die Einhaltung der Vorschriften bleibt bei dir.','No variations yet.'=>'Noch keine Varianten.','Grouped products have no own price; see each child product.'=>'Gruppierte Produkte haben keinen eigenen Preis; siehe die einzelnen Produkte.','No prices recorded yet.'=>'Noch keine Preise gespeichert.','From'=>'Ab','Regular'=>'Regulär','Sale'=>'Angebot','Sale schedule'=>'Angebotszeitraum','Price'=>'Preis','Source'=>'Quelle','Prices as entered in the shop (before the tax display setting). Newest first, up to 30 rows.'=>'Preise wie im Shop eingegeben (vor der Einstellung zur Steueranzeige). Neueste zuerst, höchstens 30 Zeilen.','(unknown before)'=>'(davor unbekannt)','lowest price in the %1$d days before the discount that started on %2$s:'=>'niedrigster Preis der %1$d Tage vor der Preisermäßigung, die am %2$s begann:','Goods that perish or expire quickly. Only used when the perishable-goods exemption is enabled in Pricetrail settings.'=>'Waren, die schnell verderben oder eine kurze Haltbarkeit haben. Wird nur verwendet, wenn die Ausnahme für schnell verderbliche Waren in den Pricetrail-Einstellungen aktiviert ist.','Pricetrail: lowest price in the 30 days before a discount'=>'Pricetrail: niedrigster Preis der 30 Tage vor einer Preisermäßigung','Pricetrail'=>'Pricetrail','Settings'=>'Einstellungen','Sorry, you are not allowed to access this page.'=>'Du hast leider keine Berechtigung, auf diese Seite zuzugreifen.','Coverage report'=>'Abdeckungsbericht','Import and tools'=>'Import und Werkzeuge','Pricetrail: lowest price before a discount'=>'Pricetrail: niedrigster Preis vor einer Preisermäßigung','This plugin helps display prices; you remain responsible for compliance. It does not give legal advice. Check the rules that apply to your shop.'=>'Dieses Plugin hilft bei der Preisanzeige; die Verantwortung für die Einhaltung der Vorschriften bleibt bei dir. Es bietet keine Rechtsberatung. Prüfe die Regeln, die für deinen Shop gelten.','The action could not be started. Action Scheduler (part of WooCommerce) is not available.'=>'Die Aktion konnte nicht gestartet werden. Action Scheduler (Teil von WooCommerce) ist nicht verfügbar.','Started in the background. Refresh this page to see the progress.'=>'Im Hintergrund gestartet. Lade die Seite neu, um den Fortschritt zu sehen.','Rules'=>'Regeln','Preset'=>'Vorlage','A preset fills the three rules below when you save. Presets are starting points, not legal advice: confirm the rules of the country you sell to. Choose "Custom rules" to set them yourself.'=>'Eine Vorlage füllt beim Speichern die drei Regeln unten aus. Vorlagen sind Ausgangspunkte, keine Rechtsberatung: Prüfe die Regeln des Landes, in das du verkaufst. Wähle „Eigene Regeln“, um sie selbst festzulegen.','Period before the discount (days)'=>'Zeitraum vor der Preisermäßigung (Tage)','At least 30 days. The period ends when the current discount started and begins at midnight that many days earlier. For progressive discounts it ends when the first discount started.'=>'Mindestens 30 Tage. Der Zeitraum endet mit dem Beginn der aktuellen Preisermäßigung und beginnt um Mitternacht entsprechend viele Tage davor. Bei schrittweisen Preisermäßigungen endet er mit dem Beginn der ersten Preisermäßigung.','Products on the market for less than the period'=>'Produkte, die kürzer als der Zeitraum angeboten werden','Hide the notice (strict)'=>'Hinweis ausblenden (streng)','Use the lowest price since the product was launched (only where your country allows a shorter period)'=>'Niedrigsten Preis seit der Markteinführung des Produkts verwenden (nur wenn dein Land einen kürzeren Zeitraum erlaubt)','Do not show the notice for products (or categories) marked as perishable. Only where your country exempts perishable goods.'=>'Keinen Hinweis für Produkte (oder Kategorien) anzeigen, die als schnell verderblich markiert sind. Nur wenn dein Land schnell verderbliche Waren ausnimmt.','Display'=>'Anzeige','Product page'=>'Produktseite','Show the notice under the price on product pages (classic templates and the Product Price block).'=>'Hinweis unter dem Preis auf Produktseiten anzeigen (klassische Templates und der Block „Produktpreis“).','Shop and category pages'=>'Shop- und Kategorieseiten','Show the notice in product lists, related products and product blocks.'=>'Hinweis in Produktlisten, ähnlichen Produkten und Produktblöcken anzeigen.','Variations'=>'Varianten','Show the notice for the selected variation of variable products.'=>'Hinweis für die ausgewählte Variante variabler Produkte anzeigen.','Incomplete history'=>'Unvollständige Historie','Hide the notice when the price history does not cover the whole period (recommended). When unchecked, the text below is shown instead.'=>'Hinweis ausblenden, wenn die Preishistorie nicht den ganzen Zeitraum abdeckt (empfohlen). Wenn deaktiviert, wird stattdessen der Text unten angezeigt.','Notice text'=>'Hinweistext','Notice text (period since launch)'=>'Hinweistext (Zeitraum seit Markteinführung)','Text when the history is incomplete'=>'Text bei unvollständiger Historie','Placeholders'=>'Platzhalter','{price} the lowest price, {days} the number of days, {date} the day the discount started. Leave a text empty to use the translated default.'=>'{price} der niedrigste Preis, {days} die Anzahl der Tage, {date} der Tag, an dem die Preisermäßigung begann. Lass einen Text leer, um den übersetzten Standardtext zu verwenden.','To place the notice elsewhere, use the shortcode %s.'=>'Um den Hinweis an anderer Stelle anzuzeigen, verwende den Shortcode %s.','Data'=>'Daten','Keep history for (days)'=>'Historie aufbewahren (Tage)','Older prices are deleted daily, except the ones still needed for a running discount. Minimum 31 days.'=>'Ältere Preise werden täglich gelöscht, außer denen, die für eine laufende Preisermäßigung noch benötigt werden. Mindestens 31 Tage.','When recording starts for an existing product, assume its current price has applied since the product was last modified. Leave unchecked if other software changes prices without updating products (strict).'=>'Wenn die Aufzeichnung für ein bestehendes Produkt beginnt, annehmen, dass der aktuelle Preis seit der letzten Änderung des Produkts gilt. Deaktiviert lassen, wenn andere Software Preise ändert, ohne die Produkte zu aktualisieren (streng).','Uninstall'=>'Deinstallation','Delete the price history and settings when the plugin is deleted.'=>'Preishistorie und Einstellungen löschen, wenn das Plugin gelöscht wird.','%d product or variation is on sale.'=>'%d Produkt oder Variante ist reduziert.' . "\0" . '%d Produkte und Varianten sind reduziert.','For each one: whether the lowest prior price is known and shown, and if not, why.'=>'Für jedes: ob der niedrigste vorherige Preis bekannt ist und angezeigt wird, und falls nicht, warum.','Product'=>'Produkt','Current price'=>'Aktueller Preis','Lowest prior price'=>'Niedrigster vorheriger Preis','Discount started'=>'Preisermäßigung seit','Status'=>'Status','%1$d price records for %2$d products and variations.'=>'%1$d Preiseinträge für %2$d Produkte und Varianten.','Last catalogue check finished %1$s: %2$d products checked, %3$d records added.'=>'Letzte Katalogprüfung beendet am %1$s: %2$d Produkte geprüft, %3$d Einträge hinzugefügt.','Catalogue check running: %d products checked so far.'=>'Katalogprüfung läuft: bisher %d Produkte geprüft.','Check the catalogue'=>'Katalog prüfen','Records the current price of products that have no history yet, and marks products whose price changed without passing through WooCommerce. Runs in the background.'=>'Speichert den aktuellen Preis von Produkten, die noch keine Historie haben, und markiert Produkte, deren Preis an WooCommerce vorbei geändert wurde. Läuft im Hintergrund.','Check the catalogue now'=>'Katalog jetzt prüfen','Import history from another plugin'=>'Historie aus einem anderen Plugin importieren','Reads (never changes) the price history saved by another plugin and adds the prices from before Pricetrail started recording each product. Only import from a plugin that was active until now; a plugin that was switched off long ago has gaps that cannot be detected. Running an import twice is safe.'=>'Liest die von einem anderen Plugin gespeicherte Preishistorie (ohne sie zu ändern) und ergänzt die Preise aus der Zeit, bevor Pricetrail mit der Aufzeichnung des jeweiligen Produkts begann. Importiere nur aus einem Plugin, das bis jetzt aktiv war; ein vor langer Zeit deaktiviertes Plugin hat Lücken, die nicht erkannt werden können. Ein erneuter Import ist unbedenklich.','Plugin'=>'Plugin','Data found'=>'Gefundene Daten','Last import'=>'Letzter Import','%1$s: %2$d imported, %3$d skipped'=>'%1$s: %2$d importiert, %3$d übersprungen','Running…'=>'Läuft …','Import'=>'Importieren','Background tasks'=>'Hintergrundaufgaben','Pending tasks: %d.'=>'Ausstehende Aufgaben: %d.','View in WooCommerce → Status → Scheduled Actions'=>'In WooCommerce → Status → Geplante Aktionen ansehen','Sorry, you are not allowed to do that.'=>'Du hast leider keine Berechtigung, dies zu tun.','Lowest price in the {days} days before the discount: {price}'=>'Niedrigster Preis der letzten {days} Tage vor der Preisermäßigung: {price}','Lowest price since this product was launched ({days} days) before the discount: {price}'=>'Niedrigster Preis seit Markteinführung dieses Produkts ({days} Tage) vor der Preisermäßigung: {price}','The lowest price in the {days} days before the discount is not available.'=>'Der niedrigste Preis der letzten {days} Tage vor der Preisermäßigung ist nicht verfügbar.','Omnibus — show the lowest price (by iWorks)'=>'Omnibus — show the lowest price (von iWorks)','WC Price History for Omnibus'=>'WC Price History for Omnibus','Omnibus by iLabs'=>'Omnibus by iLabs','Pricetrail needs WooCommerce %s or newer to be active.'=>'Pricetrail benötigt ein aktives WooCommerce in Version %s oder neuer.','EU, strict: 30 days, no optional exemptions'=>'EU, streng: 30 Tage, keine optionalen Ausnahmen','Bulgaria: 30 days, no optional exemptions'=>'Bulgarien: 30 Tage, keine optionalen Ausnahmen','Germany: 30 days, perishable goods may be excluded'=>'Deutschland: 30 Tage, schnell verderbliche Waren können ausgenommen werden','Poland: 30 days, products offered for less than 30 days use the period since launch'=>'Polen: 30 Tage, für Produkte, die kürzer als 30 Tage angeboten werden, gilt der Zeitraum seit Markteinführung','Custom rules'=>'Eigene Regeln']];